from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE

def inspect_pptx(filename):
    prs = Presentation(filename)
    print(f"Slide Width: {prs.slide_width}, Slide Height: {prs.slide_height}")

    for i, slide in enumerate(prs.slides):
        print(f"\n--- Slide {i+1} ---")
        for shape in slide.shapes:
            if shape.has_text_frame:
                text = shape.text.strip()
                if text:
                    print(f"Shape ID: {shape.shape_id}, Type: {shape.shape_type}, Text: '{text}'")
                    # properties
                    print(f"  Left: {shape.left}, Top: {shape.top}, Width: {shape.width}, Height: {shape.height}")

if __name__ == "__main__":
    inspect_pptx("/root/Awesome-Agent-Papers.pptx")
